// #3257d0efcc42561f5bc1ef6c — официальный звонок максимальной длины (20 мин) до конца по таймеру: все части записи
// загружены без пропусков, склейка (end-candidate-attempt) быстрая, транскрипт ≤ 300 с от конца, отчёт ready,
// файл записи ≈ длине звонка, клик по последней реплике ставит плеер. Кейс REC-002.
// ОЧЕНЬ МЕДЛЕННЫЙ (~25–30 мин), @slow, @data, НЕ prod-safe: создаёт кандидата «QA-AUTO-REC20-…» (канал link_only —
// без письма/SMS), тратит его официальный звонок и ~20 мин AI-голоса. Кандидат не удаляется (правило проекта — только с «да»).
// Нужна активная симуляция длиной 20 мин: QA_LONG_SIMULATION (по умолчанию «QA-20MIN-1619»).
// В обычном регрессе пропускать: npm test -- --grep-invert @slow. Короткий вариант — short-call-stitch-transcript.spec.ts.
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { createCandidateLink } from '../candidate-call/support';
import { launchGuest, startOfficialCall, expectAllPartsUploaded, openBusinessApi, candidateId, waitTranscriptAndReport, checkReportPage } from './support';

const LONG_SIMULATION = process.env.QA_LONG_SIMULATION || 'QA-20MIN-1619';

test.describe('Запись звонка — склейка частей и транскрипт после длинного звонка (#3257d0efcc42561f5bc1ef6c) @call', () => {
  test('звонок 20 мин до конца по таймеру: части 0…N без пропусков, end-candidate-attempt < 30 с, транскрипт ≤ 300 с, отчёт ready, файл ≈ звонку, клик по последней реплике @desktop @data @slow #3257d0efcc42561f5bc1ef6c', async ({ asUser }) => {
    test.setTimeout(45 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-REC20-${runStamp()}`;
    const link = await createCandidateLink(business, name, LONG_SIMULATION);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}» (официальный звонок 20 мин использован), не удаляется` });

    const guest = await launchGuest();
    try {
      await startOfficialCall(guest.page, link);
      // Звонок не завершаем сами — ждём конец по таймеру симуляции (20 мин).
      await expect(guest.page.getByText('הסימולציה הושלמה')).toBeVisible({ timeout: 25 * 60_000 });
      await expect.poll(() => guest.log.endRespAt, { message: 'нет ответа end-candidate-attempt', timeout: 120_000 }).toBeTruthy();

      // Склейка: в тикете до исправления 59.7–68.3 с на 262 части; после — 8.2 с на 240 частей.
      // Источник: AC «איחוד חלקי ההקלטה אינו מוריד את החלקים בזה אחר זה … נשאר מרווח ביטחון בתקציב».
      const stitchSec = (guest.log.endRespAt! - guest.log.endReqAt!) / 1000;
      expect(guest.log.endStatus).toBe(200);
      expect(stitchSec, `end-candidate-attempt ${stitchSec.toFixed(1)} с`).toBeLessThan(30);
      expect(guest.log.endBody?.attempt?.end_reason).toBe('duration_elapsed');
      expect(guest.log.endBody?.recording?.is_partial).toBe(false);

      // Все части записи (F-36 AC1 «הקלטת השיחה במלואה»): 20 мин ≈ 240 частей.
      const parts = await expectAllPartsUploaded(guest.log);
      expect(parts, 'частей меньше, чем для 20-минутного звонка').toBeGreaterThanOrEqual(200);

      const api = await openBusinessApi(business);
      const id = await candidateId(api, name);
      const { report, transcriptSec, reportSec } = await waitTranscriptAndReport(api, id);
      expect(report.attempt?.end_reason).toBe('duration_elapsed');
      expect(report.attempt?.duration_seconds, 'звонок максимальной длины (20 мин)').toBeGreaterThanOrEqual(1190);
      // Источник: AC «התמלול מוכן בתוך 300 שניות מסוף השיחה» (факт 13.10: +85–86 с).
      expect(transcriptSec).toBeLessThanOrEqual(300);
      // Источник: decisions «סך הזמן עד דוח מוכן אינו עולה על 10 דקות» (факт 13.10: +94.5 с).
      expect(reportSec).toBeLessThanOrEqual(600);

      const page = await checkReportPage(business, id, report);
      test.info().annotations.push({
        type: 'timing',
        description: `частей ${parts}, склейка ${stitchSec.toFixed(1)} с, транскрипт ≤ +${transcriptSec.toFixed(0)} с, отчёт +${reportSec.toFixed(0)} с, файл ${page.decodedSec.toFixed(1)} с / звонок ${report.attempt?.duration_seconds} с, сегментов ${page.segments}`,
      });
    } finally {
      await guest.browser.close();
    }
  });
});
